INSERT INTO cmd_command_type VALUES('open_ship_mortgage','Open ship mortgage'),('pay_ship_mortgage','Pay ship mortgage');
INSERT INTO cmd_domain_event_type VALUES('ship_mortgage_opened','Ship mortgage opened'),('ship_mortgage_paid','Ship mortgage payment posted'),('ship_mortgage_satisfied','Ship mortgage satisfied');
CREATE TABLE cmd_ship_mortgage_opening_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),ship_mortgage_id bigint NOT NULL UNIQUE,ship_id bigint NOT NULL,actor_id bigint NOT NULL,cash_price_minor bigint NOT NULL CHECK(cash_price_minor>0),payment_amount_minor bigint NOT NULL CHECK(payment_amount_minor>0),term_months smallint NOT NULL CHECK(term_months=480),next_due_day bigint NOT NULL,FOREIGN KEY(ship_mortgage_id,campaign_id) REFERENCES ship_mortgage(ship_mortgage_id,campaign_id),FOREIGN KEY(ship_id,campaign_id) REFERENCES ship_ship(ship_id,campaign_id),FOREIGN KEY(actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id));
CREATE TABLE cmd_ship_mortgage_payment_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),ship_mortgage_id bigint NOT NULL,payment_number smallint NOT NULL CHECK(payment_number BETWEEN 1 AND 480),amount_minor bigint NOT NULL CHECK(amount_minor>0),financial_transaction_id bigint NOT NULL UNIQUE,balance_after_minor bigint NOT NULL,next_due_day bigint,mortgage_status text NOT NULL CHECK(mortgage_status IN('current','satisfied')),UNIQUE(ship_mortgage_id,payment_number),FOREIGN KEY(ship_mortgage_id,campaign_id) REFERENCES ship_mortgage(ship_mortgage_id,campaign_id),FOREIGN KEY(financial_transaction_id,campaign_id) REFERENCES fin_transaction(transaction_id,campaign_id));
